/// Owned snapshot of a [`crate::Tool`] for cross-async-boundary use
/// inside [`ModelRequest`].
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ToolDef {
    /// Identifier the model uses when emitting a tool call.
    pub name: String,
    /// One-line tool description shown to the model.
    pub description: String,
    /// JSON Schema for the tool's argument object.
    pub schema: serde_json::Value,
}

/// Provider-tuning knobs.
///
/// Field shape grew in SMA-316 to cover the surface OpenAI needs;
/// SMA-317 (Anthropic) may reshape if Anthropic's protocol demands it.
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
#[non_exhaustive]
pub struct ModelSettings {
    /// Sampling temperature. Provider-defined default when unset.
    pub temperature: Option<f32>,
    /// Nucleus-sampling top-p. Provider-defined default when unset.
    pub top_p: Option<f32>,
    /// Cap on output tokens per response. Maps to `max_tokens` on
    /// OpenAI Chat and to `max_output_tokens` on OpenAI Responses.
    pub max_output_tokens: Option<u32>,
    /// Caller's tool-selection preference. See [`ToolChoice`].
    pub tool_choice: Option<ToolChoice>,
    /// Caller's response-shape preference. See [`ResponseFormat`].
    pub response_format: Option<ResponseFormat>,
    /// OpenAI Responses-API server-side state token. **Caller-managed:**
    /// when set, callers MUST trim [`ModelRequest::messages`] to only
///     ) -> Result<ToolOutput, ToolError> {
///         Ok(ToolOutput::new(args))
///     }
/// }
///
/// let _tool = EchoTool {
///     schema: json!({ "type": "object" }),
/// };
/// ```
#[async_trait]
pub trait Tool<Ctx>: Send + Sync
where
    Ctx: Send + Sync + 'static,
{
    /// Tool name, unique per registry. Used by the model to address calls.
    fn name(&self) -> &str;
    /// Human-readable description, shown to the model.
    fn description(&self) -> &str;
    /// JSON Schema for the argument payload.
    fn schema(&self) -> &serde_json::Value;
    /// Optional JSON Schema for the return payload. Default is `None`.
    fn output_schema(&self) -> Option<&serde_json::Value> {
        None
    }

    /// This tool's side-effect profile. Default [`ToolEffect::SideEffect`]
    /// (safe-by-default): an undeclared tool is treated as side-effecting, so
    /// `Plan` mode blocks it.
    fn effect(&self) -> ToolEffect {
        ToolEffect::SideEffect
    }

    /// Execute the tool with `args` (a JSON value matching [`Tool::schema`]).
    async fn invoke(
        &self,
        ctx: &ToolContext<Ctx>,
        args: serde_json::Value,
    ) -> Result<ToolOutput, ToolError>;
}

/// Bundle of the run's permission/guard/redaction config, projected from
/// [`crate::RunContext`] into [`ToolContext`]. A struct (not a long positional
/// arg list) so same-typed fields like `default_guards`/`redact_output` can't be
/// transposed silently.
pub(crate) struct PermissionFields<Ctx>
where
        let model = std::sync::Arc::clone(&self.model);
        let tools = self.tools.clone();
        let effective_config = ctx
            .run_config()
            .cloned()
            .unwrap_or_else(|| self.config.clone());
        let max_turns = effective_config.max_turns;
        let parallel_tool_call_limit = effective_config.parallel_tool_call_limit;
        let model_settings = self.model_settings.clone();
        let agent_name = self.name.clone();
        let instructions_text = self.instructions.render(&ctx);
        let output_type = self.output_type.clone();
        let tool_defs: Vec<crate::ToolDef> = tools
            .iter()
            .map(|t| crate::ToolDef {
                name: t.name().to_owned(),
                description: t.description().to_owned(),
                schema: t.schema().clone(),
            })
            .collect();
        let handoffs = self.handoffs.clone();
        let input_guardrails = self.input_guardrails.clone();
        let output_guardrails = self.output_guardrails.clone();
        let agent_hooks = self.hooks.clone();
        let max_agent_depth = effective_config.max_agent_depth;
        let mut input = input;
            _ => None,
        })
        .unwrap_or_default()
}

/// The synthetic `ToolDef` the model sees for one handoff (no arguments — the
/// conversation is the payload).
fn handoff_tool_def(def: &crate::HandoffDef) -> ToolDef {
    ToolDef {
        name: def.tool_name.clone(),
        description: def.description.clone(),
        schema: serde_json::json!({
            "type": "object",
            "properties": {},
            "additionalProperties": false
        }),
    }
}

/// Real tools + synthetic transfer tools, for an unconstrained model turn.
fn turn_tools(ctx: &TransitionCtx<'_>) -> Vec<ToolDef> {
    let mut tools = ctx.tools.to_vec();
    tools.extend(ctx.handoffs.iter().map(handoff_tool_def));
    #[test]
    fn tool_effect_default_is_side_effect() {
        assert_eq!(ToolEffect::default(), ToolEffect::SideEffect);
    }
}

